import React from 'react';
import { NavLink, useNavigate, Outlet } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import api from '../../api/axios';
import '../../styles/admin.css';

export default function AdminLayout() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = async () => {
    try { await api.post('/logout'); } catch (e) { /* ignore */ }
    logout();
    navigate('/admin/login');
  };

  return (
    <div className="admin-shell">
      <aside className="admin-sidebar">
        <div className="admin-logo">PHISHBOOK <span>Admin</span></div>
        <nav>
          <NavLink to="/admin/dashboard">Dashboard</NavLink>
          <NavLink to="/admin/users">User Management</NavLink>
          <NavLink to="/admin/login-activity">Login Activity</NavLink>
          <NavLink to="/admin/dummy-accounts">Dummy Accounts</NavLink>
        </nav>
        <div className="admin-sidebar-footer">
          <div className="admin-user">{user?.first_name} {user?.last_name}</div>
          <button onClick={handleLogout}>Logout</button>
        </div>
      </aside>
      <main className="admin-content">
        <Outlet />
      </main>
    </div>
  );
}
